mapper.select:
SELECT COUNT(*) FROM tb_cmn_code
WHERE code = #{code}
  AND (p_cid = #{parentCid, jdbcType=BIGINT}
       OR (p_cid IS NULL AND #{parentCid, jdbcType=BIGINT} IS NULL))
  AND cid <> #{cid}

SELECT FROM tb_cmn_code c LEFT JOIN tb_cmn_code p ON p.cid = c.p_cid
ORDER BY c.c_lvl, c.p_cid NULLS FIRST, c.cid
LIMIT #{pageSize} OFFSET #{firstIndex}
